// tests/golden/DecorationCases -- the DECLARATIVE SPEC of the decoration baselines: each case a small page and the
// header, footer or Bates number on it, as RawPage writes it. Stage 7 T14, decision D7-44 (`Stage7-Assembly-Plan.md`
// §3), guide case A-98 (`Stage7-Assembly-Testing-Guide.md` §5.16).
//
// WHY A SPEC IN CODE, as `AppearanceCases` is: a decoration is OUR output, so a fixture holding it would be the
// product's bytes committed as data and regenerated by the code it judges. Each case is a page 288 by 216 points (a
// grey band and a black bar of content, so a shrink has something to shrink), maybe turned, and a spec -- fixed field
// values, a fixed key -- and `decorationPdf` writes it THROUGH THE SHIPPED PATH: the page opened by
// `pdf/ops/MutationSinkImpl`, the spec laid out by `core::layoutHeaderFooter`, handed to `addPageDecorations` and
// written by `RevisionWriter::compose`, then verified as a save verifies. So the baseline is what a save writes.
//
// Stage 7 T15 adds the WATERMARK cases (`watermark-<name>`): text, an image and a PDF page as sources, at an opacity,
// turned, scaled, anchored with an offset, tiled, behind and in front, on a page turned by `/Rotate` -- the image a
// generated gradient with alpha, the page one written here and copied as an insert copies it (`ObjectGraphCopier`).
//
// The baselines are `golden/decoration/<name>.png` at `kDecorationDpi`, captured by `golden-update --decoration
// --reason "…"` and compared by `render.golden.decoration *` with the corpus suite's thresholds. **What a green run
// claims is the suite's usual and no more**: our decorations rasterize on THIS rasterizer the way they did when each
// baseline was LOOKED AT and kept -- not that another reader draws them so (M-07, Acrobat), not that they are right.
//
// Compiled into `rawpage_golden_tests` and `golden-update` alike, so the two read one spec.

#ifndef RAWPAGE_TESTS_GOLDEN_DECORATIONCASES_H
#define RAWPAGE_TESTS_GOLDEN_DECORATIONCASES_H

#include "core/doc/HeaderFooter.h"
#include "core/doc/Watermark.h"

#include <optional>

#include <QString>

#include <string>
#include <vector>

namespace rawpage::golden {

inline constexpr int kDecorationDpi = 144;
inline constexpr double kDecorationPageWidth = 288.0;
inline constexpr double kDecorationPageHeight = 216.0;

struct DecorationCase {
    QString name;                 // `decoration/<name>.png`
    QString note;                 // what it shows
    int rotate = 0;               // the page's /Rotate
    core::DecorationKind kind = core::DecorationKind::HeaderFooter;
    core::HeaderFooterSpec spec;
    // Draws text in a face resolved from THIS machine -- a CJK collection, which no reader carries -- so its baseline is
    // a claim about this machine's fonts, as the manifest's `machineDependent` cases are (`tst_golden`).
    bool machineDependent = false;
    // Stage 7 T15 (D7-45, guide A-99): a WATERMARK instead of `spec` -- laid out by `core::layoutWatermark`.
    std::optional<core::WatermarkSpec> watermark = std::nullopt;
};

const std::vector<DecorationCase>& decorationCases();

// The case's page with its decoration, written and verified through the sink; empty when any step refused.
std::string decorationPdf(const DecorationCase& item);

QString decorationBaselinePath(const DecorationCase& item);

} // namespace rawpage::golden

#endif // RAWPAGE_TESTS_GOLDEN_DECORATIONCASES_H
